'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';

export default function Navbar() {
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');

  useEffect(() => {
    const resolveTheme = () => {
      const probeY = 40;
      const probeX = window.innerWidth / 2;
      const element = document.elementFromPoint(probeX, probeY) as HTMLElement | null;
      const section = element?.closest<HTMLElement>('[data-nav-theme]');
      const nextTheme = section?.dataset.navTheme === 'light' ? 'light' : 'dark';

      setTheme((current) => (current === nextTheme ? current : nextTheme));
    };

    let frameId = 0;

    const onViewportChange = () => {
      if (frameId) return;

      frameId = window.requestAnimationFrame(() => {
        frameId = 0;
        resolveTheme();
      });
    };

    resolveTheme();
    window.addEventListener('scroll', onViewportChange, { passive: true });
    window.addEventListener('resize', onViewportChange);

    return () => {
      if (frameId) {
        window.cancelAnimationFrame(frameId);
      }
      window.removeEventListener('scroll', onViewportChange);
      window.removeEventListener('resize', onViewportChange);
    };
  }, []);

  const logoColorClass = theme === 'dark' ? 'text-white/35' : 'text-black/30';
  const navTextColorClass = theme === 'dark' ? 'text-white/55' : 'text-black/45';
  const navHoverColorClass = theme === 'dark' ? 'hover:text-white/80' : 'hover:text-black/70';

  return (
    <header className="fixed left-0 top-0 z-50 w-full px-6 py-6 md:px-12 lg:px-20">
      <nav className="flex items-center justify-between">
        <Link
          href="/"
          className={`text-[13px] font-bold uppercase tracking-[0.14em] transition-colors duration-200 ${logoColorClass}`}
        >
          VBV
        </Link>

        <div
          className={`flex gap-[10px] text-[10px] font-medium uppercase tracking-[0.14em] transition-colors duration-200 md:gap-10 md:text-[11px] ${navTextColorClass}`}
        >
          <a href="#work" className={`transition-colors duration-200 ${navHoverColorClass}`}>
            Work
          </a>
          <a href="#about" className={`transition-colors duration-200 ${navHoverColorClass}`}>
            Info
          </a>
          <a href="#contact" className={`transition-colors duration-200 ${navHoverColorClass}`}>
            Contact
          </a>
        </div>
      </nav>
    </header>
  );
}